quests[70061] = { id = 70061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training Wings", progress = "Some whelps need more encouragement than the rest. Of course, we love them all.", completion = "It is good to see our young flying with such joy and liberty in their hearts. Thank you for helping them achieve that.", objectives = "Guide a whelp to eliminate 12 Agitated Weedlings, 6 Intrusive Pupstingers, and 1 Relentless Gust.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70062] = { id = 70062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Some Call Me Bug Catcher", description = "Ah, young {race}, I could use your help. I have raised generations of life here. \n\nNone more my favorite than the ducklings. But my body has grown old and weak... still that does not stop the cycle.\n\nI need you to catch food for my brood.", progress = "There is a beginning and end to all creatures. It does not matter how long or how short.", completion = "Oh...  Back so soon?  It only felt like a moment. \n\nYou got the good parts as well!\n\nFirequackers and Pilot are going to love the chitin.", objectives = "Collect 6 Flyspawn Beetle Parts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70064] = { id = 70064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Imbu!" }
quests[70066] = { id = 70066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming the Hold" }
quests[70067] = { id = 70067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Message to the Nokhud" }
quests[70068] = { id = 70068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cobalt Catastrophe" }
quests[70069] = { id = 70069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Others Call Me Duck Herder", description = "My days grow shorter... Still my duties are not done. \n\nThe brood should all be by the creek. I leave them there hoping they will grow more independent. Soon they will have to fend for themselves.\n\nToday they will rely on you. Please bring them the food you caught, and then the ducklings to me. Be wary of Pilot, she is always jumping off something.", completion = "My beautiful ducklings! You look so strong!\n\nPilot, come. Play time is over. \n\n<Pilot refuses to leave your side and tries to hide behind your legs. Until Gracus scoops her up.> \n\nSeems she likes you.", objectives = "Feed 4 ducklings and return to Gracus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70070] = { id = 70070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "But... I Am the Hero of Ducks", description = "Hold on... there is something...\n\n<Gracus looks around.> \n\nFirequackers! The boy must have gone down the river again! No matter how often I tell him, he always tries to play with the hornswogs!\n\nI need you to go check on him. I hope he didn't get swallowed again.", completion = "He was swallowed by the--\n\nFirequackers still has much to learn. \n\nPilot on the other hand has already taken a liking to you. The smartest of the brood and the one most ready to leave. \n\nFor all that you have done, I thank you! Take care of my sweet duckling!", objectives = "Find Firequackers and make sure he gets to Gracus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70071] = { id = 70071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering the Magic" }
