quests[70195] = { id = 70195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taken By Storm", description = "According to reports, the Nokhud were accompanied by an outsider wielding never-before-seen magic. This outsider tore through our ranks like a tempest. \n\nIf the Nokhud have allies who can wreak this much havoc, we must find out as much as we can about them.\n\nI have sent my ohuna, Altan, to find this outsider. She has not flown back, and I am concerned. {name}, can you search for clues about this outsider and see what has become of Altan?", progress = "I have my suspicions about the identity of these new Nokhud allies, but I must be sure.", completion = "So, we are at war with both the Nokhud and the Primalists. Now it is even more critical that we get Ohn'ahra and the dragons on our side.\n\nThank you for your assistance, {name}, and thank you for saving Altan.", objectives = "Rescue Altan and search for clues about the outsider.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70196] = { id = 70196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pruning the Preserve" }
quests[70197] = { id = 70197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of the Isles", description = "Are ye ready for the adventure of a lifetime? I know I sure am!\n\nOur allies have gathered and supplies are loaded. So what're you waiting for?\n\nMeet me at the Stormwind docks. It's time to set sail for the Dragon Isles!", completion = "Ye sure look ready. Let's get underway!", objectives = "Meet Toddy Whiskers at the Stormwind Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70198] = { id = 70198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of the Isles", description = "Our allies gather in Durotar. This is a very exciting time!\n\nJoin us, {name}! It's time to set sail for the Dragon Isles!", completion = "I am so excited! Are you ready to begin our adventure together?", objectives = "Meet Naleidea Rivergleam in Durotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70199] = { id = 70199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch and Release: Scalebelly Mackerel", progress = "If we over-fish this spot there will be no fish left for anyone. Sustainability is key.\n\nBring me any fish you want to return to the pools.", completion = "I will return these to the pools. Managing the fisheries is an important responsibility." }
quests[70200] = { id = 70200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch and Release: Thousandbite Piranha", progress = "If we over-fish this spot there will be no fish left for anyone. Sustainability is key.\n\nBring me any fish you want to return to the pools.", completion = "I will return these to the pools. Managing the fisheries is an important responsibility." }
quests[70201] = { id = 70201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch and Release: Aileron Seamoth", progress = "If we over-fish this spot there will be no fish left for anyone. Sustainability is key.\n\nBring me any fish you want to return to the pools.", completion = "I will return these to the pools. Managing the fisheries is an important responsibility." }
quests[70202] = { id = 70202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch and Release: Cerulean Spinefish", progress = "If we over-fish this spot there will be no fish left for anyone. Sustainability is key.\n\nBring me any fish you want to return to the pools.", completion = "I will return these to the pools. Managing the fisheries is an important responsibility." }
quests[70203] = { id = 70203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch and Release: Temporal Dragonhead", progress = "If we over-fish this spot there will be no fish left for anyone. Sustainability is key.\n\nBring me any fish you want to return to the pools.", completion = "I will return these to the pools. Managing the fisheries is an important responsibility." }
quests[70204] = { id = 70204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Golden Claw", description = "<This might be something Emila Bellocq is looking for.>", completion = "The dragonflights definitely had an affinity for gold, didn't they? It's everywhere! And now we have it.\n\nI'll make sure this goes under lock and key.", objectives = "Deliver the item to Emilia Bellocq.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70207] = { id = 70207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tail Fragment", description = "<This might be something Emila Bellocq is looking for.>", completion = "It needs restoration... but it's fine craftsmanship. I will catalogue this one myself!", objectives = "Deliver the item to Emilia Bellocq.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70209] = { id = 70209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quacks and Attacks" }
quests[70210] = { id = 70210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tradition Not Forgotten", description = "One tradition for the Aylaag as we stay at this camp is for our members to make the pilgrimage to the Eternal Kurgans to ask for journeys safe from that which plagued our ancestors. The presence of the Nokhud has made this pilgrimage perilous.\n\nIf you do not mind, I would ask you would uphold our tradition for us.", progress = "Clan Nokhud and Ukhel desecrate the spiritual land just by their presence.", completion = "I owe you much. It is hard to ask an outsider for help with something so important to our clan, but I do not see another option.", objectives = "Place incense and clear out ghostly beasts from the Eternal Kurgans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70211] = { id = 70211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stomping Explorers", description = "The influx of explorers to the Dragon Isles isn't letting up anytime soon. We need to replenish your stock of Explorer's Plate Boots. Even serevite can't withstand what is being asked of these boots. Get to work and see me when you have finished the job.", progress = "Are you finished already?", completion = "This is fine craftsmanship. We will hear the lovely clang of more plate boots around here soon. \n\nYour skill is progressing well. Here is something you can study to improve your blacksmithing even more.", objectives = "Craft 2 Explorer's Plate Boots for Metalshaper Kuroko in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70212] = { id = 70212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Penumbrus" }
quests[70213] = { id = 70213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harkyn Grymstone" }
quests[70215] = { id = 70215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curiosity is Key", description = "My hesitation to discuss these symbols was not for a lack of trust in you, but rather the unknown nature of these symbols and the stones upon which they reside.\n\nYes, stones. Multiple, in fact. Scattered across the Isles.\n\n<Warpcaster Delandra glances at you. A hint of curiosity and excitement glows in her eyes.>\n\nYou did not know.\n\nVery well. Your persistence and willingness to seek me out shows that you are keen to understand your recent discovery. Perhaps it is time we discuss this at length.", completion = "I have prepared a vessel which allows one to capture and store rampant energy.\n\nThis knowledge is not known to many. It would be wise to proceed with caution.", objectives = "Speak with Warpcaster Delandra at Camp Antonidas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70220] = { id = 70220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shady Sanctuary", description = "We must inform the rest of the green dragonflight that the barrier to the Ancient Bough is under threat. Gerithus and I have much to discuss.\n\n{name}, I will place my mark upon you. The other dragons who see it will know that you are my trusted messenger.\n\nGo and rally my flight. They must know and prepare for the battle ahead.", progress = "Go with my blessing.", completion = "My dragonflight is ready, then? Good. We will confront our enemies with everything we have.", objectives = "Speak to Guard-Captain Alowen, Sariosa, Sidra the Mender, and Viranikus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70221] = { id = 70221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Show Your Mettle", objectives = "Hey there {name}! The Artisan's Consortium would like to thank you for everything you've done for us. We'd like to give you some Artisan's Mettle free of charge.\n\nMaybe use it to fill some recrafting orders for us!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70224] = { id = 70224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fetid Threat" }
quests[70229] = { id = 70229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boku the Mystic", description = "The mystics were called away to Ridgewater Retreat a few days ago, but one mystic remains. His name is Boku. He can be found on top of the hill at the Ohn'ahran shrine.\n\nHe's just an initiate, but he should be able to commune with Ohn'ahra and acquire her blessing. With Ohn'ahra on our side, we might be able to win this war before it starts.", completion = "Who are you? Did Ohn'ahra send you?", objectives = "Find Boku in Teerakai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70233] = { id = 70233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Axe Shortage", description = "A mix-up with orders resulted in a severe shortage of new axes for our explorers. We have an immediate need for more Draconium Axes and are looking for all blacksmiths to pitch in. In return, I will impart new Blacksmithing Knowledge to you to assist in making even more epic pieces.", progress = "Are you finished already?", completion = "These will add to our dwindling stockpile nicely. \n\nYour skill is progressing well. As promised, here is something you can study to improve your blacksmithing.", objectives = "Craft 2 Draconium Axes for Metalshaper Kuroko in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70234] = { id = 70234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All this Hammering", description = "The anvils have not been quiet since the Dragon Isles awoke. The anvils are doing fine, but our hammers are starting to crack. To keep up with the demand, we need to restock.", progress = "Are you finished already?", completion = "You can't have enough hammers can you? \n\nYour skill is progressing well. Here, have this to study so you can continue to improve your blacksmithing.", objectives = "Craft 2 Draconium Blacksmith's Hammers for Metalshaper Kuroko in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70235] = { id = 70235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repair Bill", description = "The Dragon Isles have not experienced conflict like this in millennia. Our work is not in dispute, but any good armor suffers from all of this constant use. I have a big order for Serevite Repair Hammers and I need everyone I can get to fill it. If you help out, I will again give you more information to expand your Dragon Isles Blacksmithing skills.", progress = "Are you finished already?", completion = "I haven't had this many repair hammers ready to go. Want to wager how long before our customers get through them?\n\nAs promised, here is this to study. You can always improve your blacksmithing.", objectives = "Craft 6 Serevite Repair Hammers for Metalshaper Kuroko in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70236] = { id = 70236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dislodged Dragoneye", description = "<This might be something Emila Bellocq is looking for.>", completion = "Oh... look at that sparkle! It's hard not to just... slip it in my pocket. But I won't. I'll put it somewhere safe that's not on my person.", objectives = "Deliver the item to Emilia Bellocq.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70239] = { id = 70239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untold Regrets", description = "Duroz is old, sick, and stubborn as a kodo. There was no stopping him getting on the airship to come here. Best I could do was come be his walking stick.\n\nI've seen him in pain enough times on the battlefield to know when he's hiding it. He's been getting worse every day out here. Can you help me get him to the potion makers? Ale's not doing the trick anymore. \n\nIf you can carry our weapons, I can help him walk.", progress = "I wish there was more I could do.", completion = "<Bathoras frowns in concern as he looks over the old orc.> \n\nI will examine him and see what I can do.", objectives = "Walk with Duroz and Kolgar to find help.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70240] = { id = 70240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pain Management", description = "It is a good thing you brought him here when you did. I can tell he is in a great deal of pain, though he bears it well. So must we all when it comes time.\n\nI am afraid that it is age that ails him and not illness, but I may be able to relieve some portion of his suffering.\n\nWould you mind gathering some snapflowers, shallowlilies, and pure water from the garden nearby? I can create a pain medicine with these components, if you find enough.", progress = "Was the dragonspawn... willing to make anything?", completion = "<Duroz takes the potion from you with a small, sad smile. He almost looks disappointed by something.>", objectives = "Gather 5 Milky Snapflowers, 3 Blooming Shallowlilies, and a Filled Life Pools Vial.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70241] = { id = 70241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bitter End", description = "It just happened. I--He was sleeping and I looked away and-- We came back here every day, he just wanted to sit with the whelps, I didn't know he--\n\n<Kolgar's face is clearly tear-stained. He rubs his eyes with the back of his hand.>\n\nNo, I knew. I knew. But I don't know what to do now. What do I do with him?\n\nCan you-- Can you find Bathoras?", progress = "Oh, greetings once more, {name}. \n\nI have been able to make a few more batches of that medicine with all the herbs you brought me. \n\nDuroz began refusing it earlier today, but I may be able to find other uses for it.", completion = "I see, then. Sometimes there is little that can be done.", objectives = "Bring Bathoras to Duroz and Kolgar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70242] = { id = 70242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Life After Life", description = "I could sense that his friend bore a deep scar. Something in this place reopened it--perhaps so that it could heal cleanly this time.\n\nNow it is Kolgar's time to heal.\n\nIn the terrace above us, you will find my friend Trellain working with the enchanters. Tell him that I require one of the vessels he uses in his work. He will give it to you freely.", progress = "Were you able to find Trellain?", completion = "Thank you, {name}. This will be suitable.", objectives = "Collect an Inert Vessel from Trellain in the Ruby Lifeshrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70244] = { id = 70244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nokhud Can Come of This", description = "For thousands of years, the Teerai have guarded the Horn of Drusahl, our most sacred relic. By sacking this village, Balakar has betrayed everything it means to be Maruuk. There can be no redemption for him now.\n\nWe must retake the Horn before Balakar can destroy it and rescue any Teerai who yet live. I am going with you to personally bring that false Khan to justice. The Nokhud will know the wrath of the Khanam Matra!", progress = "There is no time to lose! We must re-take the village and defend the Horn of Drusahl!", completion = "What are they doing to Ohn'ahra? Balakar and Koroleth will pay dearly for this!", objectives = "Enter the village with Khanam Matra Sarest and reclaim it from the Nokhud.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70268] = { id = 70268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Memories Revived", description = "You found a partially destroyed diary. It appears to be written from the view point of a young black dragon woman, before the corruption. \n\nWhile the back part of it is illegible, skimming through the first part, a name stands out to you. Veritistrasz.", progress = "Hello young one, nice to see you again.", completion = "Oh? What's this? A Diary? I wonder what's in it.", objectives = "Give Veritistrasz the Diary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70279] = { id = 70279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of Dragons", description = "As you've no doubt seen, this land contains creatures which grow beyond their normal size.\n\nWe consider these beasts as blessed by the gods of the wild, and they are often considered honorable targets for hunters to prove their strength. One of these beasts, which we call Karkidan, is nearby. I would be most impressed if you managed to take it down.", progress = "How goes your hunt?", completion = "Admirable work! You match the prowess of Teerai's finest hunters.", objectives = "Slay Karkidan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70299] = { id = 70299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draconic Defensive", description = "I've heard words on the wind of outsiders allying with Clan Nokhud in an effort to defeat our dragon neighbors. These Primalists are a blight on the plains of our ancestors.\n\nSlay them, and bring me the cores of the elementals they command.", progress = "The dragons and our kin have long held peace. This threat to such cannot be ignored.", completion = "Hopefully that keeps Aylaag safe from the dragons' ire. Unfortunately we cannot offer anything beyond this meager assistance.", objectives = "Slay primalists in the Storm Scar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70319] = { id = 70319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nergazurai", description = "My uncle told me many tales of his battle with a hornstrider named Nergazurai. He told me of its fuchsia scales weaving through the hills of the plains as it seeks its prey, its razor-sharp talons and venomous bite.\n\nWhile I was out hunting I saw the flash, but it was too late; it left me with a nasty bite in my shoulder. He was as terrible as my uncle described, but I came out alive.\n\nI need to clean the infection from his bite. Please, collect the reagents I need. Time is of the essence.", progress = "My fever grows worse, friend. I fear if I do not clean the infection soon, it will be the death of me.", completion = "Thank you. With these reagents I should be able to stop the infection from spreading, then hopefully clear it completely. I owe you a life-debt.\n\nBe wary of Negazurai, traveler. His thirst for blood is unyielding.", objectives = "Bring an Ottuk Heart, a Rockfang Femur, a Hornstrider Scale, and a Vulture Gizzard to Muqur Rain-Touched in Timberstep Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70335] = { id = 70335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Simple Excavation Tools", objectives = "Your help is greatly appreciated! As a show of our gratitude, I want to offer you one of my special excavation tools. I also have all of these available for trade, so come and see me again if you wish to complete the set. \n\nThank you adventurer!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70337] = { id = 70337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emberwatch", description = "Hail, outsider.\n\nThe winds tell me of a group taking shelter in the ruins of Emberwatch. They seem only interested in the past while we centaur choose to live for the present under the grace of Ohn'ahra.\n\nNonetheless, they are guests in our home. I have fashioned for them these wind chimes so they may hear Ohn'ahra's presence. May it bring their hearth some joy and comfort.", completion = "What's this?\n\nHow fascinating. It must be an ancient artifact of great importance.\n\nWe will need some time to study it.", objectives = "Bring the Ohn'ir Wind Chimes to Emberwatch.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70338] = { id = 70338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Took the Kits", description = "If Sylvie is this distressed, that must mean it's her kits that are in there! \n\nWhile she was infected, the giants must have kit-napped her babies and she was too weak to save them.\n\nKits are energetic at this age, hopefully they've all been quick enough to evade the giants until now...\n\nHere, make use of my invisibility charm-- Quickly, you must save them before they're eaten!", completion = "Now that Sylvie is healing, these kits will be in good hands...\n\nEr, paws...\n\nClaws?", objectives = "Rescue the kits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70339] = { id = 70339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Tyr's Footsteps: The Ohn'ahran Plains", description = "Though you have done well in your first challenge, do not think you shall surpass all so easily. Keeper Tyr meant the Engine of Innovation to be only for those worthy enough to use it wisely. \n\nIf you are undeterred, the next challenge shall be found in the Ohn'ahran Plains. I look forward to testing your capabilities, adventurer.", completion = "<It feels as if the statue reacts to your presence, its mechanism slowly awakening and coming to life.>", objectives = "Find the Second Challenge of Tyr in the Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70341] = { id = 70341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Well-Earned Victory", description = "The smallest of things can contain the greatest of treasures.\n\nTake the essence to the Engine of Innovation.", completion = "Can you feel the potential emanating from the bottle?", objectives = "Return to the Engine of Innovation in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70351] = { id = 70351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garden Party", description = "I've been tending to this garden for years, preparing for the day I'd finally accept my Lifecalling. Now that day is here!\n\nI love flowers and all trees and plants--even the bugs that live amongst them. I can feel nature's spirit--the Great Dragon Spirit--when I tend the garden.\n\nThere's only one thing left to do. I'm going to invoke the Great Dragon Spirit, just like the legends.\n\n<Akora smiles brightly.>\n\nMeet me down in the garden by the pool where her bones rest. I'll explain more there.", completion = "Excellent! Now we can really get to work, {name}.", objectives = "Speak to Akora in the Ruby Life Pools.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70352] = { id = 70352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scaling Ever Higher", description = "You there, outsider! You have killed proto dragons before, yes?\n\nSo it stands to reason that your experience combined with my hunting prowess, we can take down quite a few! There are springs around here that attract draconic beasts. \n\nHelp me prove to my foolish other half that I am the better hunter.", progress = "How goes the hunt?", objectives = "Slay hornswogs and territorial proto drakes with Toluiqi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70355] = { id = 70355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Alchemy", objectives = "Welcome to the Dragon Isles! You seem like a skilled alchemist. Perhaps you would be interested to learn my draconic methodologies?\n\nI can teach you everything I know about alchemy. I am sure you will learn something new.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70357] = { id = 70357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Blacksmithing", objectives = "Welcome tae the Dragon Isles! You're a smithy, I'm sure o' it! Ye got the face o' one, anyways.\n\nWould ye like to know how tae work with the metals o' the Dragon Isles?\n\nI can teach ye summat new about smithin' if ye like.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70358] = { id = 70358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Blacksmithing", objectives = "Ye come to these isles to craft some new weapons or armor too? I been workin' with this new ore for a bit... I can show ye a tip or two, if yer interested.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70359] = { id = 70359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Engineering", objectives = "Hi there! Welcome to the Dragon Isles! Hey, you seem like a fellow sparky. Can I show you a couple gadgets I've been working on?\n\nI can teach you some new engineering schematics!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70360] = { id = 70360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Enchanting", objectives = "These islands are teeming with arcane power!\n\nYou look like you know your way around an enchantment or two. Want to see something impressive?\n\nI can teach you new enchantments found only on the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70361] = { id = 70361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Inscription", objectives = "Good day!\n\nYou must be the new scribe. Let me show you what I've translated so far of these draconic glyphs.\n\nI can teach you new inscription techniques of the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70362] = { id = 70362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Leatherworking", objectives = "There is more than one way to skin a beast, certainly.\n\nOf course you would know this, leatherworker. But do you know how to work with proto-drake leather?\n\nI can teach you new leatherworking techniques that should be useful on the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70363] = { id = 70363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Skinning", objectives = "Greetings and welcome to the Dragon Isles.\n\nThe blade at your side shows me you are a proficient skinner, though you seem new to these lands.\n\nWould you like me to show you how to skin the beasts of the Dragon Isles?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70364] = { id = 70364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Herbalism", objectives = "Welcome to the Ruby Life Pools, traveler.\n\nThis verdant land has a bounty to offer. Of course, as an herbalist you would know this!\n\nI can show you how to locate the herbs unique the Dragon Isles, if you would like.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70365] = { id = 70365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Jewelcrafting", objectives = "Are ye the new jewelcrafter I asked for?\n\n<Falron looks you over.>\n\nPerhaps not, but ye are a jewelcrafter. You will do.\n\nI will teach ye how to cut the gems of the Dragons Isles, since you're here.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70366] = { id = 70366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Tailoring", objectives = "Draconic weaving is an ancient art. It takes decades, perhaps centuries, to master. No better reason to start today!\n\n<Krillon eyes your hands.>\n\nDon't worry, we have tools to assist those who lack natural claws.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70368] = { id = 70368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Occupation Examination", description = "Hello! Are you interested in working with the Artisan's Consortium to earn plentiful profits and provide valuable goods and services to clients across Azeroth?\n\n...Hmm? You have no professions? What a missed opportunity!\n\n<Haephesta ponders for a moment.>\n\nI know! I will ask you a series of questions about your personality, and we will find out together which profession best suits you! How does that sound?", progress = "Quizzes solve everything!", completion = "I am glad we found a profession that suits you!\n\nBest of luck in your training! Please return to the Artisan's Consortium when you are skilled. We have many opportunities for you!", objectives = "Take Haephesta's personality quiz to find out your ideal profession.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70369] = { id = 70369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blasting the Past" }
quests[70370] = { id = 70370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Occupation Examination", description = "Hello! Are you interested in working with the Artisan's Consortium to earn plentiful profits and provide valuable goods and services to clients across Azeroth?\n\nExcellent! Which two skills have you trained in?\n\n...Hmm? You have only one profession? What a missed opportunity!\n\n<Haephesta ponders for a moment.>\n\nI know! I will ask you a series of questions about your personality, and we will find out together which second profession best complements your first one! How does that sound?", progress = "Quizzes solve everything!", completion = "I am glad we found a profession that suits you!\n\nBest of luck in your training! Please return to the Artisan's Consortium when you are skilled. We have many opportunities for you!", objectives = "Take Haephesta's personality quiz to find out your ideal profession.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70371] = { id = 70371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deathwingurlugull!", description = "Deathwingurlugull! Deathwingurlugull! Deathwingurlugull delgrbrrl!!\n\nGrrrooooooooom blarglg!!\n\n<You don't need a translation to know that they want you to bring down their murloc version of Deathwing. Before you can agree or disagree, the roars of a machine engine make their way toward you!>", progress = "Deathwingurlugull delgrbrrl!!", completion = "Lrgktrr O'Glrlrlrl!\n\n<The murlocs celebrate your deeds this day!>", objectives = "Get in the Hopper and defeat Deathwingurlugull!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70373] = { id = 70373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deathwingurlugull!", description = "Deathwingurlugull! Deathwingurlugull! Deathwingurlugull delgrbrrl!!\n\nGrrrooooooooom blarglg!!\n\n<You don't need a translation to know that they want you to bring down their murloc version of Deathwing. Before you can agree or disagree, the roars of a machine engine make their way toward you!>", progress = "Deathwingurlugull delgrbrrl!!", completion = "Frrg thrg Allrghnnge!\n\n<The murlocs celebrate your deeds this day!>", objectives = "Get in the Hopper and defeat Deathwingurlugull!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70374] = { id = 70374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Himia, the Blessed", description = "The Elements lay claim to this land and do not welcome our intrusion.\n\nO, Elements, have you forgotten our protector--Air! Invisible, yet omnipresent and vital for all existence! Forgotten, as easy as you breathe it. After facing me, you will never forget again.", completion = "So you have witnessed Himia, the Blessed.", objectives = "Defeat the elements.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70376] = { id = 70376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second Challenge of Tyr: Might", description = "<As you approach, an inscription on the statue lights up with a faint glow.>\n\n\"Wield the Keeper's power and show the undaunted determination of one who stands strong.\"", completion = "Once again, you have done well and earned your reward.", objectives = "Complete the second Challenge of Tyr in the Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70377] = { id = 70377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Derelict Fashion", description = "<A disgusting set of sunglasses is dripping with slime, but they look extremely expensive.\n\nSomeone is definitely missing these. This style is very hot right now.>", progress = "I cannot possibly be seen at the VIP area without my sunglasses!\n\nYou see, I grabbed a glider, and was getting some A-MAZ-ING pictures. I looked below, and saw all of these tiny elementals the size of ants! I thought, hah, ant-size elementals: what a great photo-op.\n\nBut when I got there, they were at least three times the size of ants. A muddy one chased me, but I am very fast.  I hate to think of what has happened to my sunglasses...", completion = "My sunglasses?! You expect a reward, I gather. You know the least you could have done is clean them.\n\n<Zeldis breathes on them, then wipes them off.>\n\nI suppose I can throw a few small coins your way.", objectives = "Find the owner of the sunglasses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70382] = { id = 70382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonrider Racing - Ruby Lifeshrine Loop" }
