quests[70413] = { id = 70413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonrider Racing - Emberflow Flight" }
quests[70414] = { id = 70414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shaky Grounds", description = "In the name of Khaz'goroth, what goes on here? \n\nThis magma works with a mind of its own, consuming these elemental cavestones from below. Tis more than chance causin' this... I aim to figure it out!\n\nPlace these Shattering Totems next to each trapped elemental to free them!", progress = "Have ye freed them all?", completion = "Good work, we will need elemental allies if we wish to solve the mystery of what is happening here!", objectives = "Place the Shattering Totems to free the trapped cavestones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
