quests[70437] = { id = 70437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Tyrhold", description = "Centuries have passed since the flights last visited Tyrhold. \n\nNevertheless, we must travel there and investigate if the Mother Oathstone still functions.\n\nCome, speak with me at the Seat of the Aspects. We must learn about the dangers we may face at Tyr's former stronghold.", progress = "It is good to see you, {name}.", completion = "This space seems clear enough.", objectives = "Meet Alexstrasza at the Seat of the Aspects.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70438] = { id = 70438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flying Fish", description = "The fish could be biting better, don't you think?\n\nYou know, that gives me an idea. Legend says these lakes and rivers did not always have fish. They say, these watering holes were stocked with fish when the dragons soaring overhead dropped them! Can you believe it?\n\nMaybe you and your drake could give it a try?", progress = "Have you dropped those fish yet?", completion = "Ha! The legends are true, how fantastic!", objectives = "Collect fish to restock the fishing hole and mount your drake to drop them from above.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70439] = { id = 70439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Arcana" }
quests[70440] = { id = 70440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dead Eyes" }
quests[70442] = { id = 70442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Banquet Battle" }
quests[70444] = { id = 70444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fields of Ferocity", description = "To the bravest Shikaar! \n\nGather your best and head on over to the Fields of Ferocity. You could be crowned the fiercest of them all!\n\nProve your might. Show us your best fight!\n\nTerms and conditions apply.", completion = "Hey, you're no centaur.\n\nEhh. You'll do.", objectives = "Meet Gurgthock at the Fields of Ferocity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70446] = { id = 70446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Personal History", description = "In delving into the archives here, I've found threads that point towards the Obsidian Observatory as a place of personal importance to the Earth-Warder. I can only guess what knowledge it may contain about the history of our flight.\n\nGiven Emberthal's interest in the subject, I informed her of my discovery. I pray that wasn't a mistake.\n\nShe has gone ahead to scout. Please, keep an eye on her. She is a competent soldier, but this subject is... troubling. Who knows what truths you may uncover.", completion = "I am confident I will be able to handle anything we encounter. Still, given the matter at hand... it was wise of Edress to send you to accompany me.", objectives = "Meet Emberthal at the Obsidian Observatory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70450] = { id = 70450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Otter Devastation", description = "Hey there, friend. These here ottuks keep stealin' my catch!\n\nPersonally, I'd blow 'em up, but our Tuskarr friends don't seem too keen on that action. I made this here Ottuk Deterent Device MK-SH4RK, but... I aint a great swimmer.\n\nYou seem like you got the goods, why don't ya do us all a favor, activate the device, swimmy-swim around over there, and scare 'em off?", progress = "You get rid of them pesky ottuks yet?", completion = "'Ey! Great job, buddy. Now let's chum these waters good!", objectives = "Scare off the Pesky Ottuks.\n\nYou may unlock only one extra fishing net per day.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70501] = { id = 70501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "License to Hunt", description = "Ah, finally ready to prove yourself as a hunter? Keep in mind this is not as simple as running around and hunting everything that moves. The Shikaar hunt with purpose. We hunt to feed and clothe the clan, to prove our strength against mighty foes, and to balance nature.\n\nWe do not hunt the land barren, we sow the seeds for future Grand Hunts as we go. Prove yourself capable of following these instructions and you may join us.\n\nHowever I do not have confidence in your friend there succeeding.", progress = "Have you completed your training?", completion = "Excellent! You are ready to join the Grand Hunts! \n\nPlease inform this Nesingwary Jr. that there is more to hunting than mindless killing and that he is unwelcome to join us.", objectives = "Complete the Grand Hunt training tasks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70502] = { id = 70502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Skies" }
quests[70503] = { id = 70503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vigilance of Tyr", description = "Bodies, broken gear, uncontrolled titan energy. What a disregard for safety, and... and protocol! It looks like they found the stone and it was unstable, bursting into pieces.\n\nFortunately, I'm particularly adept at repairing magical devices.\n\nBut before I can reform the stone we need to collect each and every piece.", progress = "I can't believe it. It's all here! Well done.", completion = "I'll head back to basecamp and have my people reconstruct this stone. Don't worry {name}, artifact restoration is our specialty.", objectives = "Recover the fragments of the stone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70507] = { id = 70507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Insight of Tyr", description = "Did ya see Szar Skeleth on your way in? It's that ruined tower to the northeast.\n\nWe've got a bit of a good news, bad news situation there. The good news is the stone's already been found. Bad news is it was found by the Sundered Flame, specifically a magic-using dracthyr named Makko. And they're using it to control gorlocs.\n\nDid I mention the dracthyr's misuse of the stone drove them mad?\n\nWell, good luck!", progress = "Turns out gorlocs don't make for good bodyguards, eh? I wonder how dangerous she could've been if she held on to her sanity.", completion = "You've got it! Don't worry about me. We should be safe to handle it unless we try to do something crazy. Like mind-controlling little fish monsters.", objectives = "Recover the Insight of Tyr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70509] = { id = 70509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Third Challenge of Tyr: Persistence", description = "<It seems those who have reawakened with the Isles have not been kind to Keeper Tyr's creations. Perhaps finding the missing pieces of the statue would help.>", progress = "<As you approach, you can feel the warmth of Titan's energy flowing through the statue once more.>", completion = "Excellent work as always. I feel that Tyr's faith in the future was not unfounded.", objectives = "Retrieve missing parts and repair the broken statue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70510] = { id = 70510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victorious", description = "Once again I ask you to bring this essence to the Engine of Innovation.", completion = "Have you noticed that each bottle is brighter when you bring it here? It shows that you are meant to walk this path.", objectives = "Return to the Engine of Innovation in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70526] = { id = 70526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohn'ahran Plains Rally", description = "Fly through the checkpoint rings marking the course." }
quests[70529] = { id = 70529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Them Home" }
quests[70530] = { id = 70530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Examination Week", description = "The students at Algeth'ar Academy ran out of solutions... again. Forgive me for asking, but could you gather more Dragon's Alchemical Solution so they can continue their studies?", progress = "The students are getting impatient.", completion = "Excellent. We will not have to cancel the exams. After all, you can't take an exam without solutions!\n\nHere, study this. Even as a skilled alchemist, there is more for you to learn.", objectives = "Craft 5 Dragon's Alchemical Solution using the Reclaim Concoctions recipe for Conflago in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70531] = { id = 70531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mana Markets", progress = "Our customers are waiting.", completion = "Thank you {name}. My alchemy is brilliant but my customer service leaves something to be desired. I am glad you were here to help me fill these orders.\n\nHere, study this. Even as a skilled alchemist, there is more for you to learn.", objectives = "Craft 10 Aerated Mana Potions for Conflago in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70532] = { id = 70532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding the Raiding", progress = "Every moment you waste, the Primalists grow stronger.", completion = "Thank you, {name}. This will revitalize the health of our injured champions and keep the Primalists at bay for another week.\n\nHere, study this. Even as a skilled alchemist, there is more for you to learn.", objectives = "Craft 10 Refreshing Healing Potions for Conflago in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70533] = { id = 70533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draught, Oiled Again", progress = "A craft without Writhefire Oil is like a dish without salt.", completion = "Wonderful, thank you. Always use a finishing reagent like Writhefire Oil for excellent craftsmanship.\n\nHere, study this. Even as a skilled alchemist, there is more for you to learn.", objectives = "Craft 6 Writhefire Oils for Conflago in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70539] = { id = 70539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And You Thought They Did Nothing", description = "Hey sparky, you know what everyone forgets they need when they're flying around on dragons? Goggles.\n\nYou know what we sold out of today? Goggles.\n\nYou know what I need from you right now? You guessed it!", progress = "<Clinkyclick is muttering to herself as she looks for something.>", completion = "Oh, great! These look perfect. Thanks!\n\nHere, take these schematics. I bet there's something in there you didn't know.", objectives = "Craft 2 Milestone Magnifiers for Clinkyclick Shatterboom in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70540] = { id = 70540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Engineer's Best Friend", description = "Hey sparky, have you seen my...\n\nErr... maybe hand me the...\n\nThat's it--I think it's time we start keeping a few more tools around this shop, you know what I'm saying?", progress = "<Clinkyclick is muttering to herself as she looks for something.>", completion = "Finally! It's like trying to craft with two hands tied behind my back without those things.\n\nHere, take these schematics. I bet there's something in there you didn't know.", objectives = "Craft 2 Draconium Encased Samophlanges for Clinkyclick Shatterboom in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70541] = { id = 70541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Tactics: Companion", description = "Your renown with the Maruuk grows. You may now hunt alongside a tenacious bakar or swift ohuna companion.", completion = "Treat your hunting companion with loyalty and respect and they will protect your life with their own.\n\nReturn when your renown grows and I will train you further.", objectives = "Choose to fight alongside a bakar or ohuna during the Grand Hunt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70542] = { id = 70542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azure Span Rally", description = "Fly through the checkpoint rings marking the course." }
quests[70545] = { id = 70545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blingtron 8000...?", description = "Hey sparky, I've got a secret project going on. People are going to go wild! But I've run out of the basics.... You wanna be a pal and get me some bolts?", progress = "<Clinkyclick is muttering to herself as she looks for something.>", completion = "Oooohhh...! <Clinkyclick begins laughing to herself, seemingly thinking about how she'll use these.>\n\nHere, take these schematics. I bet there's something in there you didn't know.", objectives = "Craft 10 Handfuls of Serevite Bolts for Clinkyclick Shatterboom in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70549] = { id = 70549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Low Hanging Fruit" }
quests[70550] = { id = 70550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to the Assembly", description = "We could use your aid.\n\nThe Sundered Flame have taken control over most of the Cobalt Assembly. \n\nPlease help us in this fight against them. Our numbers are small, but there are a few things we can do to aid you.", progress = "We can use all the help we can get.", completion = "Once we have more control over the Cobalt Assembly, we'll be able to better support our allies in the fight against the Sundered Flame.", objectives = "Speak with Xavin within the Cobalt Assembly to see what abilities are available within the area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70557] = { id = 70557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Scopes", description = "Great gadgets, sparky, do I have a big one for you today!\n\nApparently, some firework fad caught on with the hunters. They try setting them off to scare the ducks into the air. Bet the ducks are way to smart for that, but it won't stop us from profiting! Think you're up to the task?", progress = "<Clinkyclick is muttering to herself as she looks for something.>", completion = "Thanks, sparky! That should take care of this until they come up with some new hare-brained scheme.\n\nHere, take these schematics. I bet there's something in there you didn't know.", objectives = "Craft 15 Bronze Fireflight for Clinkyclick Shatterboom in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70558] = { id = 70558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disillusioned Illusions", description = "My scribe apprentice, you could not have chosen better timing.\n\nThere has been a terrible accident! All of the Illusion Parchment I ordered turned out to be real! Can you believe it! Do they think this is some game? Someone might get hurt!\n\nDo you think you could rectify this situation and create some real illusions?", progress = "Have you inscribed what I need?", completion = "Thank you a thousand times, my scribe apprentice.\n\nPlease take these glyphs as a token of my thanks. Perhaps you can study them to further your practices.", objectives = "Craft 5 Illusion Parchment: Spell Shield for Talendara in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70559] = { id = 70559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quill You Help?", description = "My scribe apprentice, I am delighted to see you.\n\nEarlier today I had a few novices come in to try their hand at inscription. They all wrote with too much force and snapped their quill nibs right off!\n\nI hate to ask, but could you craft a few more quills to keep in stock?", progress = "Have you fresh quills for my apprentices?", completion = "Thank you, my scribe apprentice. I do not know what I would do without you.\n\nPlease take these glyphs as a token of my thanks. Perhaps you can study them to further your practices.", objectives = "Craft 2 Scribe's Fastened Quill for Talendara in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70560] = { id = 70560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Most Powerful Tool: Good Documentation", description = "My scribe apprentice, do you feel ready for writing today? The Dragonscale Expedition has brought copious notes from their adventures, and they have asked that we compile their chicken-scratch penmanship into a suitable compendium for field-ready review. And oh, my hand is simply not up for the task today. Could I rely on you once more?", progress = "Have you inscribed the compendiums?", completion = "Thank you, my scribe apprentice, thank you.\n\nPlease take these glyphs as a token of my thanks. Perhaps you can study them to further your practices.", objectives = "Craft 2 Core Explorer's Compendiums for Talendara in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70561] = { id = 70561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Scribe's Tragedy", description = "My scribe apprentice! It is awful, just terrible! I cannot fathom how I am to go on in my life!\n\n<Talendara begins weeping.>\n\n...I have run out of ink! Could you please bottle some more?", progress = "Have you bottled the ink?", completion = "Thank you, my scribe apprentice. If only a mage would duplicate you...\n\nPlease take these glyphs as a token of my thanks. Perhaps you can study them to further your practices.", objectives = "Craft 5 Blazing Ink for Talendara in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70562] = { id = 70562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Plumbers, Mason", description = "Jewelcrafter, how would you feel about a chance to practice your prospecting techniques?\n\nThe architects and plumbers of the Dragonscale Expedition have requested that we acquire some stones for the construction of a new bath house. I think you will find this a suitable task to occupy you and practice your masonry.", progress = "Do you have the stones?", completion = "Nice work, {name}.\n\nHere, I made these cuts. You can study them to learn how to be a better jewelcrafter like me.", objectives = "Craft 15 Crumbled Stones for Tuluradormi in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70563] = { id = 70563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Exhibition", description = "Oh jewelcrafter, how would you feel about a chance to practice your gemcutting?\n\nI was going to put on a display of various cuts, and I suppose I could exhibit your gems as well, so long as you hurry. Submit nothing less than the highest quality for this demonstration.", progress = "Are your gems worthy of display?", completion = "Very well, I suppose these will do.\n\nHere, I made these cuts. You can study them to learn how to be a better jewelcrafter like me.", objectives = "Craft a variety of gems for Tuluradormi in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70564] = { id = 70564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spectacular", description = "Jewelcrafter, there is an exhibition coming up, and I am concerned that the clients will not be able to see the beauty of each cut without the proper lenses.\n\nYou do not need anything fancy. Just make a few loupes so our customers can see clearly.", progress = "Do you have the loupes?", completion = "Your work is appreciated... By someone, I would imagine. Probably.\n\nHere, I made these cuts. You can study them to learn how to be a better jewelcrafter like me.", objectives = "Craft 2 Sundered Onyx Loupes for Tuluradormi in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70565] = { id = 70565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Separation by Saturation", description = "Oh jewelcrafter, do you like my necklace?\n\nOf course you do. But I cannot show it off properly unless it stands out.\n\nI know! Why don't you make a few simple pendants and we shall flood the market. Once everyone is wearing your designs, my necklace will be a sparkling cut above the rest!", progress = "Do you have the pendants?", completion = "All in the name of fashion, {name}.\n\nHere, I made these cuts. You can study them to learn how to be a better jewelcrafter like me.", objectives = "Craft 2 Pendants of Impending Perils for Tuluradormi in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70567] = { id = 70567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When You Give Bakar a Bone", description = "I had some of the most beautiful bonewrought bows, but our bakar got to them before they could be put to use. Bakar love to chew bones, whether bow or not, and now they are ruined!\n\nCan you aid me in crafting replacements?", progress = "I will be far more wary of the bakar when next I carry these.", completion = "Thank you {name}.\n\nHere, take these designs. You can study them to improve your leatherworking.", objectives = "Craft 2 Bonewrought Crossbows for Hideshaper Koruz in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70568] = { id = 70568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tipping the Scales", description = "Our scale bracers are finely crafted and highly in demand. I am finding it difficult to keep up with all of the orders! Would you lend your skill in replenishing my supply?", progress = "Our goods are of the finest quality and craftsmanship. I am not surprised they sell so quickly.", completion = "Well done, {name}. \n\nHere, take these designs in return for your aid. You can study them to improve your leatherworking.", objectives = "Craft 2 Trailblazer's Scale Bracers for Hideshaper Koruz in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70569] = { id = 70569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Trisket, a Task Kit", progress = "I think Trisket will be far happier with these sturdy baskets.", completion = "Thank you for the aid, {name}.\n\nIn return, take these designs. You can study them to improve your leatherworking.", objectives = "Craft 2 Herbalist's Floral Baskets for Hideshaper Koruz in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70571] = { id = 70571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drums Here!", description = "We are known far and wide for our drums--the centaur have been honing these skills for generations. Unfortunately this means that our drums are in short supply these days.\n\nYou have skills of your own, I see. Perhaps you could help me craft a few drums for our stores?", progress = "Your skills are quite impressive--where did you learn to craft?", completion = "Ohn'ahra bless you, {name}.\n\nHere, have these designs. You can study them to improve your leatherworking.", objectives = "Craft 2 Feral Hide Drums for Hideshaper Koruz in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70572] = { id = 70572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cold Does Bother Them, Actually", progress = "Do you have the robes?", completion = "Thank you, {name}.\n\nPlease, learn from these examples. Study them to improve your tailoring.\n\nAnd stay warm.", objectives = "Craft 2 Surveyor's Cloth Robes for Fulafong in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70582] = { id = 70582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weave Well Enough Alone", progress = "Do you have the bolts?", completion = "You have done well with these, {name}.\n\nPlease, learn from these examples. Study them to improve your tailoring.\n\nAnd stay sharp.", objectives = "Craft 3 Wildercloth Bolts for Fulafong in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70586] = { id = 70586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sew Many Cooks", progress = "Do you have the chef's hats?", completion = "Thank you, {name}. You are hungry as ever for a good challenge.\n\nPlease, learn from these examples. Study them to improve your tailoring.\n\nAnd stay hungry.", objectives = "Craft 2 Wildercloth Chef's Hats for Fulafong in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70587] = { id = 70587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Knapsack Problem", progress = "Do you have the bag?", completion = "Thank you, {name}. This will do just fine.\n\nPlease, learn from these examples. Study them to improve your tailoring.\n\nAnd stay away from anyone offering you infinite storage space. You do not want to know what lies down that road.", objectives = "Craft 1 Simply Stitched Reagent Bag for Fulafong in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70589] = { id = 70589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blacksmithing Services Requested", progress = "Busy, busy, busy!", completion = "Thanks for your business! Keep on crafting, crafting, crafting!", objectives = "Fill Blacksmithing Crafting Orders for the Artisan's Consortium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
