quests[70613] = { id = 70613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Their Bark Before They Bite", progress = "Have you found enough Writhebark?", completion = "Thank you, {name}.\n\nPlease, take my field notes. Study them to improve your herbalism.", objectives = "Gather 8 Writhebark for Agrikus in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70614] = { id = 70614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bubble Craze", description = "<Agrikus shouts at you.> I have no more poppy tea!\n\n...Oh, you're not one of them. Praise the Titans. Someone made \"Bubble Poppy Tea\" the most fashionable drink on the market this week and I've sold out of the herb completely. Please, could you bring more poppies before they return in droves?", progress = "<Agrikus is trying to calm himself down.>", completion = "Thank you, {name}, thank you.\n\nPlease, take my field notes. Study them to improve your herbalism.\n\nI need to... make some tea...", objectives = "Gather 8 Bubble Poppies for Agrikus in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70615] = { id = 70615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Case of the Missing Herbs", progress = "Have you found my herbs?", completion = "Thank you, {name}. What a week this has been...\n\nPlease, take my field notes. Study them to improve your herbalism.", objectives = "Gather 8 Saxifrage for Agrikus in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70616] = { id = 70616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How Many??", description = "<Agrikus is crying as you approach.>\n\nThey did it... I cannot believe they did it...\n\nSomeone has come here and asked for the delivery of ONE THOUSAND herbs!\n\nI cannot even fathom this! It is preposterous. Ridiculous! Ludicrous!!\n\n...Please help.", progress = "Five hundred sixty one... five hundred sixty two...\n\n<Agrikus begins sobbing again.>", completion = "Oh, good. This will help. Thank for your assistance.\n\nPlease, take my field notes. Study them to improve your herbalism.\n\nI have herbs to count.", objectives = "Gather 20 Hochenblume for Agrikus in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70617] = { id = 70617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Mine, Mine, Mine", description = "There is nothing as useful as Draconium ore. So much can be done with it! It is the perfect ore, pure in every way.\n\nBring me Draconium. I must have it. You are a miner, yes? Then go mine!", progress = "Well? Have you brought me my ore?", completion = "Yes, yes, yes! This is exactly what I needed.\n\nTake my field notes when you go--I've written down some useful information about the mining process here in the Isles.", objectives = "Gather 7 Draconium Ore for Sekita the Burrower in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70618] = { id = 70618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of the Forge", description = "The forge... she calls to me. And she asks for Serevite. You there! Bring me Serevite! Yes, lots of Serevite! <Sekita begins laughing zealously.>", progress = "More for the forge, more, more!\n\n<Sekita begins laughing zealously.>", completion = "Yes, yes!\n\nThe forge is satisfied with this.\n\nTake my field notes when you go. There must be something in there that will teach you about mining.", objectives = "Gather 16 Serevite Ore for Sekita the Burrower in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70619] = { id = 70619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Study of Leather", description = "You there! Perhaps you can help me with my studies of this leather. Some of it is soft and pliable, yet other pieces have a more firm temper--the better for crafting armor, I suspect.\n\nBring me more leathers to investigate. I wish to continue my studies.", progress = "Were you able to find any leather to study?", completion = "Thank you {name}. This should help me hone my craft.\n\nHere, have my field notes. They will teach you about the beasts of this land and to better procure their hides.", objectives = "Gather 40 Resilient Leather for Ralathor the Rugged in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70620] = { id = 70620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scaling Up", description = "Many people ask me how I became so good at skinning. To them I say: it is all in the scales. \n\nAre you curious to learn more? Bring me some scales, and I will show you what I mean.", progress = "Have you found any worthy scales?", completion = "Excellent--with all that practice, now you have become better at skinning! You see? All in the scales.\n\nHere, have my field notes. They will teach you about the beasts of this land and how to better procure their hides.", objectives = "Gather 40 Adamant Scales for Ralathor the Rugged in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70621] = { id = 70621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Third Challenge of Tyr: Persistence Embodied", description = "Your third challenge was meant to have you overcome unfavorable odds. It was to help show me your persistence in all matters.\n\nI believe fighting djaradin and fixing my statue with the expectation that I would issue you a challenge is more than sufficient to fulfill your victory condition. \n\n<You think you catch a small smile play across her lips.>", completion = "Your third challenge was meant to have you overcome unfavorable odds. It was to help show me your persistence in all matters.\n\nI believe fighting djaradin and fixing my statue with the expectation that I would issue you a challenge is more than sufficient to fulfill your victory condition. \n\n<You think you catch a small smile play across her lips.>", objectives = "Accept the Bottled Essence from Maiden of Inspiration.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70622] = { id = 70622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resupply Three-Falls" }
