quests[70625] = { id = 70625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spellforged Creations" }
quests[70627] = { id = 70627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What of the Winterpelt Clan?", description = "We could join another clan... if we knew it to be safe.\n\nI worry the Primalists tempted other clans as they did ours. \n\nThis \"Dragonscale Expedition\" tells me they have a clawhold near the Winterpelt clan.\n\nThey may be tainted. Or they may heed our warning. With either truth, they need us.\n\nThere is a \"furbolg expert,\" Sonova Snowden, in Theron's Watch. Please go to him and learn what he knows.", completion = "Regretfully, friend... I've got bad news for ya about the Winterpelt furbolg.", objectives = "Meet Sonova Snowden at Theron's Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70629] = { id = 70629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assaulting the Shore" }
