quests[70632] = { id = 70632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cataloging the Waking Shores" }
quests[70633] = { id = 70633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fueling the Engine", description = "You have done well to pass the first challenge that Keeper Tyr left behind. Though this is but the first step on your journey I have faith you shall do well. You have earned your chance at furthering yourself in unlocking the secrets of the Forge. \n\nAdd the Bottled Essence to the Engine of Innovation and see what occurs.", progress = "<The Engine hums quietly as you approach>", completion = "A Spark of Ingenuity. An item that can unlock potential unheard of since the time of Tyr himself.\n\nI am sure you shall use it wisely.", objectives = "Use the Bottled Essence to empower the Engine of Innovation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70634] = { id = 70634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lashed Out" }
