quests[70640] = { id = 70640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Boss", description = "<The page's script glows with a soft blue light.>\n\nPreviously a cherished plaything of Malygos, the elemental Frigellus suffered from his master's neglect. \n\nWhile this once-happy settlement crumbled apace, the churlish and playful creature grew warped and twisted by the evils that plague this land.\n\nPlease see that it is safely neutralized.\n\nBring word of your success to Custodian Cynegos.", objectives = "Kill Frigellus near Camp Antonidas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70641] = { id = 70641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Waking Oath", progress = "There is much for the {race} to learn about the flights, {name}.", completion = "We all share stories of growth. I hope you have come to understand more of where we began and where we strive to reach.", objectives = "Speak with members of the red dragonflight around the Ruby Lifeshrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70643] = { id = 70643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Explosives" }
