quests[70646] = { id = 70646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pressure Valve" }
quests[70647] = { id = 70647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh Where, Oh Where Can He Be?", description = "{name}, I am glad to see you! I am worried sick and could use your help.\n\nRecently, I rescued an abandoned proto-drake whelp. I named him Lubbins because he is so lovely! I brought him here to care for him and hopefully find him a good home as someone's pet. \n\nBut now he is missing, and I am concerned that he is lost or hurt. I need to keep watch over the rest of my little ones, otherwise I would go searching for him myself. Would you please look for him?", progress = "I hope Lubbins is safe. I am terribly worried.", completion = "Thank you, {name}. I am so relieved to see little Lubbins safe and sound.\n \nOh! He seems to have taken a liking to you!", objectives = "Rescue Lubbins and bring him back to Jyhanna at the Little Scales Daycare in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70648] = { id = 70648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firava the Rekindler" }
quests[70649] = { id = 70649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swab Swog" }
quests[70650] = { id = 70650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Tyr's Footsteps: The Waking Shores", description = "You have proven yourself well so far, and though I have great faith you are worthy of the Engine I still must challenge you as is my designation. \n\nGo to the Waking Shores and find my statue and you shall receive further instructions.", completion = "<This once majestic and imposing statue now lies in ruin.>", objectives = "Find the Third Challenge of Tyr in the Waking Shores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
